solution:
const userSettings = { theme: "dark", notifications: null, sound: undefined }
const defaults = { theme: "light", notifications: true, sound: true, autoSave: true }
return {
  theme: userSettings.theme ?? defaults.theme,
  notifications: userSettings.notifications ?? defaults.notifications,
  sound: userSettings.sound ?? defaults.sound,
  autoSave: userSettings.autoSave ?? defaults.autoSave
}
